37	const FIRST_INSURANCE_PERCENT = 10;
38	
39	// Multiply before dividing: `amount * 1.1` drifts (115.00000000000001) and
40	// Math.ceil turns the drift into a whole extra gold piece. The spec requires
41	// intermediates to stay exact, so every percentage goes through here.
42	const percentOf = (amount: number, percent: number): number =>
43	  (amount * percent) / 100;
44	
45	// Rounding always favours MHPCO: premiums round up, payouts round down.
46	const roundPremium = (amount: number): number => Math.ceil(amount);
47	
48	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
49	
50	const quoteStep = (step: Step): QuoteResult => {
51	  const basePremium = step.items.reduce(
52	    (sum, item) => sum + basePremiumOf(item),
53	    0,
54	  );
55	  const firstInsuranceSurcharge = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
56	
57	  return {
58	    premium: roundPremium(
59	      basePremium + firstInsuranceSurcharge + PROCESSING_FEE,
60	    ),
61	  };
62	};
63	
64	export const runScenario = (scenario: Scenario): ScenarioOutcome => ({
65	  results: scenario.steps.map(quoteStep),
66	});
